-- NEXUS CRM PostgreSQL schema
-- Run this file in pgAdmin Query Tool while connected to your target database.

CREATE TABLE IF NOT EXISTS "Trainees" (
    "TraineeID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FullName" TEXT NOT NULL,
    "EmailAddress" TEXT UNIQUE,
    "PhoneNumber" TEXT,
    "PostalCode" TEXT,
    "StateOfResidence" TEXT
);

CREATE TABLE IF NOT EXISTS "Applications" (
    "ApplicationID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TraineeID" INTEGER NOT NULL REFERENCES "Trainees"("TraineeID") ON DELETE CASCADE,
    "Timestamp" TIMESTAMPTZ,
    "CurrentStatus" TEXT,
    "WillJoinITPHTraining" TEXT,
    "FinancialStatus" TEXT,
    "AttendingLanguageCourse" TEXT,
    "EnglishLevel" TEXT,
    "DutchLevel" TEXT,
    "UnderPressure" TEXT,
    "CompletedBootcamp" TEXT,
    "AttendedOnlineITCourse" TEXT,
    "ITExperience" TEXT,
    "IncludedInProject" TEXT,
    "WillingnessToWork" TEXT,
    "MotivationForJoining" TEXT,
    "ApplicationTerm" TEXT,
    "ReasonsForApplyingToVIT" TEXT,
    "MentorMeeting" TEXT,
    "GreenCheck" TEXT,
    "InternalTracking1" TEXT,
    "InternalTracking2" TEXT,
    "InternalTracking3" TEXT,
    "ProcessingStatus" TEXT
);

CREATE TABLE IF NOT EXISTS "Mentors" (
    "MentorID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MeetingDate" TIMESTAMPTZ,
    "MentorFullName" TEXT,
    "TraineeID" INTEGER REFERENCES "Trainees"("TraineeID") ON DELETE SET NULL,
    "HasRelevantKnowledge" TEXT,
    "EligibleForVITProject" TEXT,
    "Thoughts" TEXT,
    "AvailabilityStatus" TEXT,
    "Comments" TEXT,
    "VITGroup" TEXT,
    "SecondaryScore" TEXT
);

CREATE TABLE IF NOT EXISTS "Users" (
    "UserID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username" TEXT NOT NULL UNIQUE,
    "Password" TEXT NOT NULL,
    "Role" TEXT NOT NULL DEFAULT 'user'
);

CREATE TABLE IF NOT EXISTS "ProjectTracking" (
    "ProjectTrackingID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TraineeID" INTEGER NOT NULL REFERENCES "Trainees"("TraineeID") ON DELETE CASCADE,
    "ProjectSubmissionDate" DATE,
    "ProjectReviewDate" DATE
);

CREATE INDEX IF NOT EXISTS "idx_Applications_TraineeID" ON "Applications"("TraineeID");
CREATE INDEX IF NOT EXISTS "idx_Mentors_TraineeID" ON "Mentors"("TraineeID");
CREATE INDEX IF NOT EXISTS "idx_ProjectTracking_TraineeID" ON "ProjectTracking"("TraineeID");

-- VIT cohort history from the workbook's separate history sheet.
CREATE TABLE IF NOT EXISTS "VITHistory" (
    "VITHistoryID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "VITGroup" TEXT,
    "CandidateName" TEXT,
    "Email" TEXT
);

CREATE TABLE IF NOT EXISTS "AppSchemaMigrations" (
    "MigrationKey" TEXT PRIMARY KEY,
    "AppliedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
